const pptxgen = require('pptxgenjs');

const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

const theme = {
  primary: "1E293B",    // Slate 800 - dark text/background
  secondary: "475569",  // Slate 600 - muted text
  accent: "2563EB",     // Blue 600 - highlights
  light: "F1F5F9",      // Slate 100 - light background
  bg: "FFFFFF"          // White - default slide background
};

function addBadge(slide, pageNum) {
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fill: { color: theme.accent },
    rectRadius: 0.15
  });
  slide.addText(String(pageNum).padStart(2, '0'), {
    x: 9.1, y: 5.15, w: 0.6, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });
}

function addTitle(slide, titleText) {
  slide.addText(titleText, {
    x: 0.5, y: 0.3, w: 9.0, h: 0.8,
    fontSize: 28, fontFace: "Arial",
    color: theme.primary, bold: true, align: "left"
  });
  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 1.1, w: 9.0, h: 0,
    line: { color: theme.accent, width: 2 }
  });
}

// SLIDE 1: TITLE SLIDE
const slide1 = pres.addSlide();
slide1.background = { color: theme.bg };
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 5.625, fill: { color: theme.primary }
});
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 4.5, w: 10, h: 1.125, fill: { color: theme.accent }
});
slide1.addText("SmolVLM", {
  x: 0.5, y: 1.5, w: 9, h: 1,
  fontSize: 64, fontFace: "Arial", color: "FFFFFF", bold: true, align: "left"
});
slide1.addText("Redefining Small and Efficient Multimodal Models", {
  x: 0.5, y: 2.6, w: 9, h: 1,
  fontSize: 28, fontFace: "Arial", color: theme.light, align: "left"
});
slide1.addText("Hugging Face & Stanford University", {
  x: 0.5, y: 4.6, w: 9, h: 1,
  fontSize: 20, fontFace: "Arial", color: "FFFFFF", align: "left", valign: "middle"
});

// SLIDE 2: PROBLEM MOTIVATION
const slide2 = pres.addSlide();
slide2.background = { color: theme.bg };
addTitle(slide2, "Large VLMs Are Powerful but Impractical for Edge Deployment");
addBadge(slide2, 2);

slide2.addText([
  { text: "State-of-the-Art Reality:\n", options: { bold: true, fontSize: 22, color: theme.primary, breakLine: true } },
  { text: "Current flagship VLMs require massive compute and memory, preventing local execution on mobile and edge devices.\n\n", options: { fontSize: 18, color: theme.secondary, breakLine: true } },
  { text: "Memory Bottlenecks:\n", options: { bold: true, fontSize: 22, color: theme.primary, breakLine: true } },
  { text: "• Molmo-A1B-7B requires 27.7 GB of GPU RAM to run.\n", options: { fontSize: 18, color: theme.secondary, breakLine: true } },
  { text: "• Idefics-80B uses 80 billion parameters, requiring multi-GPU setups.\n\n", options: { fontSize: 18, color: theme.secondary, breakLine: true } },
  { text: "The Goal:\n", options: { bold: true, fontSize: 22, color: theme.primary, breakLine: true } },
  { text: "A compact VLM architecture enabling sub-1GB local inference, preserving privacy, low latency, and offline availability.", options: { fontSize: 18, color: theme.secondary } }
], { x: 0.5, y: 1.5, w: 9, h: 3.5, valign: "top" });

// SLIDE 3: ARCHITECTURE OVERVIEW
const slide3 = pres.addSlide();
slide3.background = { color: theme.bg };
addTitle(slide3, "SmolVLM Architecture: Image Splitting & Pixel Shuffle");
addBadge(slide3, 3);

const steps = ["1. Image Splitting", "2. Vision Encoder\n(SigLIP)", "3. Pixel Shuffle\n(r=4)", "4. Linear Projection", "5. SmolLM2"];
steps.forEach((step, idx) => {
  slide3.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5 + (idx * 1.85), y: 2.5, w: 1.6, h: 1.2,
    fill: { color: theme.light },
    line: { color: theme.accent, width: 2 },
    rectRadius: 0.15
  });
  slide3.addText(step, {
    x: 0.5 + (idx * 1.85), y: 2.5, w: 1.6, h: 1.2,
    fontSize: 14, fontFace: "Arial", color: theme.primary, bold: true, align: "center", valign: "middle"
  });
  if (idx < 4) {
    slide3.addShape(pres.shapes.RIGHT_ARROW, {
      x: 2.15 + (idx * 1.85), y: 2.9, w: 0.15, h: 0.4,
      fill: { color: theme.secondary }
    });
  }
});
slide3.addText("Pipeline Flow: High-resolution images are split into sub-images, encoded by a lightweight SigLIP vision encoder, compressed heavily via space-to-depth pixel shuffle, projected linearly, and finally fed into the SmolLM2 language model token space.", {
  x: 0.5, y: 4.2, w: 9, h: 1, fontSize: 16, color: theme.secondary, italic: true
});

// SLIDE 4: COMPUTE ALLOCATION
const slide4 = pres.addSlide();
slide4.background = { color: theme.bg };
addTitle(slide4, "Finding 1: Smaller Vision Encoders Outperform");
addBadge(slide4, 4);

slide4.addText([
  { text: "Balanced Compute Allocation\n", options: { bold: true, fontSize: 20, color: theme.primary, breakLine: true } },
  { text: "A critical discovery for compact VLMs is that matching a small language model with an oversized vision encoder degrades performance. The vision encoder must be scaled relative to the LLM backbone.", options: { fontSize: 16, color: theme.secondary } }
], { x: 0.5, y: 1.5, w: 4.2, h: 2.5, valign: "top" });

let dataChart4 = [
  {
    name: "93M SigLIP-B/16",
    labels: ["135M LM Base", "1.7B LM Base"],
    values: [85, 75]
  },
  {
    name: "428M SigLIP-SO400M",
    labels: ["135M LM Base", "1.7B LM Base"],
    values: [65, 88]
  }
];
slide4.addChart(pres.charts.BAR, dataChart4, {
  x: 5.0, y: 1.3, w: 4.5, h: 3.5,
  barDir: "col",
  barGrouping: "clustered",
  showLegend: true, legendPos: "b",
  title: "Performance Relative to Encoder vs LM Sizing", showTitle: true,
  titleFontSize: 12, titleColor: theme.primary,
  valAxisLabelFormatCode: "0",
  catAxisLabelColor: theme.secondary, catAxisLabelFontSize: 12,
  chartColors: [theme.accent, theme.secondary]
});

// SLIDE 5: TOKEN COMPRESSION
const slide5 = pres.addSlide();
slide5.background = { color: theme.bg };
addTitle(slide5, "Finding 3: Aggressive Pixel Shuffle (r=4) Compression");
addBadge(slide5, 5);

slide5.addText([
  { text: "16× Visual Token Reduction\n", options: { bold: true, fontSize: 22, color: theme.primary, breakLine: true } },
  { text: "• Pixel shuffle (space-to-depth) rearranges spatial features into depth channels.\n", options: { fontSize: 18, color: theme.secondary, breakLine: true } },
  { text: "• While large VLMs typically use r=2 (4× reduction), small VLMs strongly benefit from r=4 (16× reduction).\n", options: { fontSize: 18, color: theme.secondary, breakLine: true } },
  { text: "• Eases attention overhead, enabling high-resolution and multi-image modeling.", options: { fontSize: 18, color: theme.secondary } }
], { x: 0.5, y: 1.5, w: 5.5, h: 3, valign: "top" });

// Pixel Shuffle 4x4 -> 1 block
slide5.addShape(pres.shapes.RECTANGLE, {
  x: 6.5, y: 2.0, w: 1.6, h: 1.6, fill: { color: theme.light }, line: { color: theme.primary, width: 2 }
});
slide5.addText("4x4 Spatial Grid\n(16 tokens)", {
  x: 6.5, y: 3.8, w: 1.6, h: 0.5, align: "center", color: theme.primary, fontSize: 12, bold: true
});
slide5.addShape(pres.shapes.RIGHT_ARROW, {
  x: 8.25, y: 2.6, w: 0.4, h: 0.3, fill: { color: theme.accent }
});
slide5.addShape(pres.shapes.RECTANGLE, {
  x: 8.8, y: 2.3, w: 0.8, h: 1.0, fill: { color: theme.secondary }, line: { color: theme.primary, width: 2 }
});
slide5.addText("r=4 Depth\n(1 thick token)", {
  x: 8.5, y: 3.8, w: 1.4, h: 0.5, align: "center", color: theme.primary, fontSize: 12, bold: true
});

// SLIDE 6: CONTEXT LENGTH SCALING
const slide6 = pres.addSlide();
slide6.background = { color: theme.bg };
addTitle(slide6, "Finding 2: Extending Context Length (2K to 16K)");
addBadge(slide6, 6);

slide6.addText([
  { text: "Scaling Context Unlocks High Resolution\n", options: { bold: true, fontSize: 22, color: theme.primary, breakLine: true } },
  { text: "Extending context length is critical for multiple sub-images and video sequences.\n\n", options: { fontSize: 18, color: theme.secondary, breakLine: true } },
  { text: "Methodology:\n", options: { bold: true, fontSize: 20, color: theme.primary, breakLine: true } },
  { text: "• Increased the RoPE (Rotary Position Embedding) base from 10K to 273K.\n", options: { fontSize: 18, color: theme.secondary, breakLine: true } },
  { text: "• Fine-tuned on a heavily curated mixture of long and short-context visual data.\n\n", options: { fontSize: 18, color: theme.secondary, breakLine: true } },
  { text: "Result: The SmolVLM 2.2B model supports full 16K context; smaller 256M/500M variants effectively utilize an 8K context window.", options: { fontSize: 18, color: theme.accent, bold: true } }
], { x: 0.5, y: 1.5, w: 9, h: 3.5, valign: "top" });

// SLIDE 7: BENCHMARK PERFORMANCE
const slide7 = pres.addSlide();
slide7.background = { color: theme.bg };
addTitle(slide7, "SmolVLM Achieves Competitive Performance");
addBadge(slide7, 7);

const tableData = [
  [
    { text: "Capability", options: { fill: theme.primary, color: "FFFFFF", bold: true, fontSize: 14 } },
    { text: "SmolVLM 256M", options: { fill: theme.primary, color: "FFFFFF", bold: true, fontSize: 14 } },
    { text: "SmolVLM 500M", options: { fill: theme.primary, color: "FFFFFF", bold: true, fontSize: 14 } },
    { text: "SmolVLM 2.2B", options: { fill: theme.primary, color: "FFFFFF", bold: true, fontSize: 14 } },
    { text: "Best Efficient OS", options: { fill: theme.primary, color: "FFFFFF", bold: true, fontSize: 14 } }
  ],
  ["Single-Image", "55.3%", "64.7%", "74.8%", "70.1% (Molmo-A1B-7B)"],
  ["Multi-task", "33.2%", "37.4%", "46.5%", "38.2% (Molmo-A1B-7B)"],
  ["Video", "37.2%", "44.8%", "53.7%", "46.6% (InternVL2-2B)"],
  [
    { text: "Average All", options: { bold: true, fill: theme.light } },
    { text: "44.0%", options: { bold: true, fill: theme.light } },
    { text: "51.0%", options: { bold: true, fill: theme.light } },
    { text: "59.8%", options: { bold: true, fill: theme.accent, color: "FFFFFF" } },
    { text: "-", options: { bold: true, fill: theme.light } }
  ],
  [
    { text: "GPU RAM Usage", options: { bold: true, color: theme.accent } },
    { text: "0.8 GB", options: { bold: true, color: theme.accent } },
    { text: "1.2 GB", options: { bold: true, color: theme.accent } },
    { text: "4.9 GB", options: { bold: true, color: theme.accent } },
    { text: "27.7 GB (Molmo)", options: { bold: true, color: "FF0000" } }
  ]
];
slide7.addTable(tableData, {
  x: 0.5, y: 1.5, w: 9, rowH: 0.5,
  border: { type: "solid", color: "E2E8F0" },
  align: "center", valign: "middle", fontSize: 14, color: theme.secondary
});
slide7.addText("Highlight: SmolVLM-256M surpasses the 300× larger Idefics-80B, proving extreme architectural efficiency.", {
  x: 0.5, y: 4.8, w: 9, h: 0.5, fontSize: 14, color: theme.accent, italic: true
});

// SLIDE 8: ON-DEVICE DEPLOYMENT
const slide8 = pres.addSlide();
slide8.background = { color: theme.bg };
addTitle(slide8, "Real-Time Inference via HuggingSnap on Edge");
addBadge(slide8, 8);

slide8.addText([
  { text: "Zero Cloud Dependency\n", options: { bold: true, fontSize: 22, color: theme.primary, breakLine: true } },
  { text: "Deployed via the HuggingSnap iOS app, ensuring absolute privacy, zero network latency, and offline availability.\n\n", options: { fontSize: 18, color: theme.secondary, breakLine: true } },
  { text: "Throughput (SmolVLM-256M):\n", options: { bold: true, fontSize: 20, color: theme.primary, breakLine: true } },
  { text: "• Apple Pro M1 Max (64GB): ~80 tokens/sec\n", options: { fontSize: 18, color: theme.secondary, breakLine: true } },
  { text: "• Apple MacBook Air M3 (16GB): ~55 tokens/sec\n", options: { fontSize: 18, color: theme.secondary, breakLine: true } },
  { text: "• Batch Size 64 Optimization: Scales to nearly 1,000 tokens/sec", options: { fontSize: 18, color: theme.accent, bold: true } }
], { x: 0.5, y: 1.5, w: 5, h: 3.5, valign: "top" });

let dataChart8 = [
  {
    name: "Tokens/sec",
    labels: ["M3 Air", "M1 Max Pro"],
    values: [55, 80]
  }
];
slide8.addChart(pres.charts.BAR, dataChart8, {
  x: 5.5, y: 1.5, w: 4, h: 3.2,
  barDir: "bar",
  barGrouping: "standard",
  showLegend: false,
  title: "On-Device Throughput", showTitle: true,
  titleFontSize: 14, titleColor: theme.primary,
  valAxisLabelFormatCode: "0",
  catAxisLabelColor: theme.secondary, catAxisLabelFontSize: 12,
  chartColors: [theme.accent]
});

// SLIDE 9: KEY TAKEAWAYS
const slide9 = pres.addSlide();
slide9.background = { color: theme.primary };
slide9.addText("Key Takeaways: Design Principles for Efficient VLMs", {
  x: 0.5, y: 0.3, w: 9.0, h: 0.8, fontSize: 24, fontFace: "Arial", color: "FFFFFF", bold: true, align: "left"
});
slide9.addShape(pres.shapes.LINE, { x: 0.5, y: 1.1, w: 9.0, h: 0, line: { color: theme.accent, width: 2 } });
addBadge(slide9, 9);

slide9.addText([
  { text: "1. Balance Encoder-LM Compute\n", options: { bold: true, fontSize: 22, color: "FFFFFF", breakLine: true } },
  { text: "   Smaller LMs require downscaled vision encoders (e.g., 93M SigLIP) to maximize efficiency.\n\n", options: { fontSize: 18, color: theme.light, breakLine: true } },
  { text: "2. Extended Context is Mandatory\n", options: { bold: true, fontSize: 22, color: "FFFFFF", breakLine: true } },
  { text: "   Scaling from 2K to 16K unlocks complex video and high-res image capabilities.\n\n", options: { fontSize: 18, color: theme.light, breakLine: true } },
  { text: "3. Aggressive Token Compression Works\n", options: { bold: true, fontSize: 22, color: "FFFFFF", breakLine: true } },
  { text: "   Applying r=4 pixel shuffle (16× reduction) drastically reduces multi-image attention overhead.\n\n", options: { fontSize: 18, color: theme.light, breakLine: true } },
  { text: "4. Sub-1GB Inference Changes the Paradigm\n", options: { bold: true, fontSize: 22, color: "FFFFFF", breakLine: true } },
  { text: "   SmolVLM-256M proves deliberate architecture outperforms raw parameter scale on the edge.", options: { fontSize: 18, color: theme.light, breakLine: true } }
], { x: 0.5, y: 1.5, w: 9, h: 3.5, valign: "top" });

pres.writeFile({ fileName: '/app/output/final_deck.pptx' })
  .then(fileName => {
    console.log(`Successfully generated ${fileName}`);
  })
  .catch(err => {
    console.error(`Error generating presentation: ${err}`);
  });

